constexpr double lcg_a = 1664525;
constexpr double lcg_c = 1013904223;
constexpr double lcg_m = std::numeric_limits<double>::max();

double sum = 0.0;
double x;
double y;

for (int i = 0; i < n_points; ++i) {
    // Linear Congruential Generator (LCG) for random number generation
    seed = (static_cast<unsigned int>(lcg_a * seed) + lcg_c) % static_cast<unsigned int>(lcg_m);
    x = a + (static_cast<double>(seed) / static_cast<double>(lcg_m)) * (b - a);

    // Evaluate function at random point
    y = f(x);

    // Accumulate sum
    sum += y;
}

// Calculate mean value estimate of the integral
return (b - a) * (sum / static_cast<double>(n_points));
// END_CODE

